package com.beeboee.magnot.server;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.registry.MagnotItems;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Player;import net.minecraftforge.event.entity.player.*;import net.minecraftforge.eventbus.api.SubscribeEvent;public final class MagnotForgeEvents{private MagnotForgeEvents(){}@SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent e){if(e.getEntity() instanceof ServerPlayer p)MagnotNetwork.sync(p);}@SubscribeEvent public static void dimension(PlayerEvent.PlayerChangedDimensionEvent e){if(e.getEntity() instanceof ServerPlayer p)MagnotNetwork.sync(p);}@SubscribeEvent public static void left(PlayerInteractEvent.LeftClickBlock e){if(e.getEntity() instanceof Player p&&p.getMainHandItem().is(MagnotItems.FERROUS_TUBE.get()))e.setCanceled(true);}}
